/**
 * Category metadata
 * Each category has a display name and an icon (emoji)
 */
const CATEGORIES = {
  climate:     { name: "Climate", icon: "☀️", description: "Weather conditions year-round" },
  cost:        { name: "Cost", icon: "💰", description: "Cost of living and affordability" },
  wifi:        { name: "WiFi", icon: "📶", description: "Internet speed and reliability" },
  nightlife:   { name: "Nightlife", icon: "🌙", description: "Bars, clubs, and social scene" },
  nature:      { name: "Nature", icon: "🌲", description: "Access to parks, beaches, mountains" },
  safety:      { name: "Safety", icon: "🛡️", description: "Personal safety and low crime" },
  food:        { name: "Food", icon: "🍽️", description: "Quality and variety of cuisine" },
  community:   { name: "Community", icon: "👥", description: "Digital nomad community size" },
  english:     { name: "English", icon: "💬", description: "How widely English is spoken" },
  visa:        { name: "Visa", icon: "🛂", description: "Ease of getting/extending visas" },
  culture:     { name: "Culture", icon: "🎭", description: "Museums, arts, history, and cultural experiences" },
  cleanliness: { name: "Cleanliness", icon: "✨", description: "Street cleanliness and general tidiness" },
  airquality:  { name: "Air Quality", icon: "💨", description: "Average air quality throughout the year" }
};

/**
 * Get list of all category keys in consistent order
 * @returns {string[]} Array of category keys
 */
function getCategoryKeys() {
  return ['climate', 'cost', 'wifi', 'nightlife', 'nature', 'safety', 'food', 'community', 'english', 'visa', 'culture', 'cleanliness', 'airquality'];
}

// Render a country flag emoji as a self-hosted SVG <img> (consistent across platforms).
function flagSvg(emoji){
  if(!emoji) return '';
  const pts=[...emoji];
  if(pts.length!==2) return emoji;
  const code=pts.map(p=>String.fromCharCode(p.codePointAt(0)-0x1F1E6+97)).join('');
  return '<img class="flag-img" src="/assets/flags/'+code+'.svg" alt="" loading="lazy">';
}
